from sophont.attributes.characteristic import Characteristic; from sophont.attributes.gene import Gene; c1 = Characteristic(code=(0, 0, 0)); c2 = Characteristic(code=(0, 0, 0)); print('Characteristic identity:', c1 is c2); g1 = Gene(c1, 1, 0); g2 = Gene(c2, 1, 0); print('Gene identity:', g1 is g2); print('Delegation works:', g1.get_code() == c1.get_code()); print('Cache sizes - Char:', Characteristic.cache_size(), 'Gene:', Gene.cache_size())